/** Now = canonical command center. Nothing appears here from guessed feature state. */
public final class FeedActivity extends Activity {
    private LinearLayout content;private SwipeRefreshLayout swipe;private TextView systemLine;private FrameLayout statusSpot;private final Handler ui=new Handler(Looper.getMainLooper());
    @Override public void onCreate(Bundle s){super.onCreate(s);render();}
    @Override protected void onResume(){super.onResume();refresh();}

    private void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(LifeOsUi.BG);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(LifeOsUi.dp(this,16),LifeOsUi.dp(this,7),LifeOsUi.dp(this,12),LifeOsUi.dp(this,2));statusSpot=new FrameLayout(this);statusSpot.setClickable(true);statusSpot.setFocusable(true);statusSpot.setContentDescription("LifeOS intelligence status");statusSpot.setOnClickListener(v->startActivity(new Intent(this,SystemStatusActivity.class)));top.addView(statusSpot,new LinearLayout.LayoutParams(LifeOsUi.dp(this,24),LifeOsUi.dp(this,36)));TextView brand=LifeOsUi.text(this,"LifeOS",20.5f,LifeOsUi.TEXT);LifeOsUi.weight(brand,700);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,-2,1);bp.leftMargin=LifeOsUi.dp(this,8);top.addView(brand,bp);TextView avatar=LifeOsUi.avatar(this,"K");avatar.setContentDescription("Settings and diagnostics");avatar.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));top.addView(avatar,new LinearLayout.LayoutParams(LifeOsUi.dp(this,36),LifeOsUi.dp(this,36)));root.addView(top);systemLine=LifeOsUi.text(this,"",9.8f,LifeOsUi.MUTED);LifeOsUi.weight(systemLine,500);systemLine.setPadding(LifeOsUi.dp(this,16),0,LifeOsUi.dp(this,16),LifeOsUi.dp(this,3));systemLine.setVisibility(View.GONE);root.addView(systemLine);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.setVerticalScrollBarEnabled(false);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(LifeOsUi.dp(this,16),LifeOsUi.dp(this,2),LifeOsUi.dp(this,16),LifeOsUi.dp(this,14));sc.addView(content);swipe=new SwipeRefreshLayout(this);swipe.setColorSchemeColors(LifeOsUi.BLUE);swipe.setProgressBackgroundColorSchemeColor(LifeOsUi.SURFACE);swipe.addView(sc);swipe.setOnRefreshListener(this::manualRefresh);root.addView(swipe,new LinearLayout.LayoutParams(-1,0,1));root.addView(LifeOsUi.bottomNav(this,FeedActivity.class));setContentView(root);}
    private void manualRefresh(){refresh();try{BackgroundBrain.poke(this);}catch(Throwable ignored){}if(!BackgroundModelManager.isReadyFast(this))NotificationBrain.analyzeForeground(this,r->{if(!isFinishing())refresh();});ui.postDelayed(()->{if(swipe!=null)swipe.setRefreshing(false);refresh();},1000);}

    private void refresh(){if(content==null)return;content.removeAllViews();updateSystemStatus(IntelligenceStatus.snapshot(this));List<ObligationRepository.ObligationObject> obligations=ObligationRepository.open(this,80);PersistentActionQueue queue=new PersistentActionQueue(this);List<PersistentActionQueue.Item> actions=queue.pending();List<CalendarEventRepository.CalendarEventObject> upcoming=CalendarEventRepository.availability(this)==CalendarEventRepository.Availability.OPERATIONAL?CalendarEventRepository.upcoming(this,40,7L*86400000L):java.util.Collections.emptyList();TextView date=LifeOsUi.text(this,new SimpleDateFormat("EEE, d MMM yyyy",Locale.getDefault()).format(new Date()),10.8f,LifeOsUi.MUTED);LifeOsUi.weight(date,500);content.addView(date);TextView greet=LifeOsUi.text(this,greeting()+", Kareem.",21.5f,LifeOsUi.TEXT);LifeOsUi.weight(greet,700);greet.setPadding(0,LifeOsUi.dp(this,3),0,0);content.addView(greet);TextView sub=LifeOsUi.text(this,"Here's what matters right now.",11.7f,LifeOsUi.MUTED);LifeOsUi.weight(sub,500);sub.setPadding(0,LifeOsUi.dp(this,3),0,LifeOsUi.dp(this,10));content.addView(sub);stats(obligations.size(),actions.size(),upcoming.size());quickCapture();
        sectionRow("Priority for today",obligations.isEmpty()?"":"See all",()->startActivity(new Intent(this,CapabilityActivity.class).putExtra("capability","commitments")));for(int i=0;i<Math.min(3,obligations.size());i++)obligationCard(obligations.get(i));if(obligations.isEmpty())quiet("Nothing is canonically waiting on you right now.");
        if(!upcoming.isEmpty()){sectionRow("Upcoming",upcoming.size()>2?"See all":"",()->startActivity(new Intent(this,CapabilityActivity.class).putExtra("capability","events")));for(int i=0;i<Math.min(2,upcoming.size());i++)eventCard(upcoming.get(i));}
        if(!actions.isEmpty()){sectionRow("Ready actions","See all",()->startActivity(new Intent(this,ActionCenterActivity.class)));for(int i=0;i<Math.min(2,actions.size());i++)approvalCard(queue,actions.get(i));}
    }

    private void quickCapture(){sectionRow("Quick capture","",()->{});LinearLayout row=new LinearLayout(this);quick(row,"Voice",LifeOsIconView.MIC,LifeOsUi.BLUE,()->startActivity(new Intent(this,VoiceRecorderActivity.class)));quick(row,"File",LifeOsIconView.FILE,LifeOsUi.AMBER,()->startActivity(new Intent(this,CapabilityActivity.class).putExtra("capability","files")));quick(row,"Place",LifeOsIconView.PLACE,LifeOsUi.BLUE,()->startActivity(new Intent(this,CapabilityActivity.class).putExtra("capability","places")));quick(row,"Decision",LifeOsIconView.DECISION,LifeOsUi.PINK,()->startActivity(new Intent(this,LifeSignalsActivity.class)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,LifeOsUi.dp(this,46));p.bottomMargin=LifeOsUi.dp(this,1);content.addView(row,p);}
    private void quick(LinearLayout row,String label,String icon,int color,Runnable action){Button b=LifeOsUi.button(this,label);b.setCompoundDrawablePadding(LifeOsUi.dp(this,4));b.setOnClickListener(v->action.run());b.setContentDescription("Quick capture "+label);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,46),1);if(row.getChildCount()>0)p.leftMargin=LifeOsUi.dp(this,6);row.addView(b,p);}

    private void updateSystemStatus(IntelligenceStatus.Snapshot s){statusSpot.removeAllViews();View ring=LifeOsUi.statusRing(this,s,20);statusSpot.addView(ring,new FrameLayout.LayoutParams(LifeOsUi.dp(this,20),LifeOsUi.dp(this,20),Gravity.CENTER));String line="";if("download_failed".equals(s.modelState)||"download_paused".equals(s.modelState)||"unavailable".equals(s.modelState))line="LifeOS needs attention · tap the ring for status";else if(s.pending>0||s.backgroundRunning||"downloading".equals(s.modelState)||"verifying".equals(s.modelState))line=s.pending>0?s.pending+" items analyzing in the background":"LifeOS is analyzing in the background";if(line.isEmpty())systemLine.setVisibility(View.GONE);else{systemLine.setText(line);systemLine.setTextColor(line.startsWith("LifeOS needs")?LifeOsUi.AMBER:LifeOsUi.MUTED);systemLine.setVisibility(View.VISIBLE);}}
    private void stats(int attention,int actions,int upcoming){LinearLayout row=new LinearLayout(this);stat(row,String.valueOf(attention),"Need attention",LifeOsIconView.ALERT,attention>0?LifeOsUi.RED:LifeOsUi.TERTIARY,()->startActivity(new Intent(this,CapabilityActivity.class).putExtra("capability","commitments")));stat(row,String.valueOf(actions),"Ready actions",LifeOsIconView.ACTION,LifeOsUi.BLUE,()->startActivity(new Intent(this,ActionCenterActivity.class)));stat(row,CalendarEventRepository.availability(this)==CalendarEventRepository.Availability.OPERATIONAL?String.valueOf(upcoming):"—","Upcoming",LifeOsIconView.UPCOMING,LifeOsUi.TERTIARY,()->startActivity(new Intent(this,CapabilityActivity.class).putExtra("capability","events")));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=LifeOsUi.dp(this,2);content.addView(row,p);}
    private void stat(LinearLayout row,String value,String label,String iconName,int color,Runnable click){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(LifeOsUi.dp(this,8),LifeOsUi.dp(this,7),LifeOsUi.dp(this,6),LifeOsUi.dp(this,6));c.setBackground(LifeOsUi.round(this,LifeOsUi.SURFACE,LifeOsUi.BORDER,13));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(LifeOsUi.icon(this,iconName,color,12),new LinearLayout.LayoutParams(LifeOsUi.dp(this,12),LifeOsUi.dp(this,12)));TextView n=LifeOsUi.text(this,value,16.5f,color);LifeOsUi.weight(n,700);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-2,-2);np.leftMargin=LifeOsUi.dp(this,5);top.addView(n,np);c.addView(top);TextView l=LifeOsUi.text(this,label,9.1f,LifeOsUi.MUTED);LifeOsUi.weight(l,500);l.setPadding(0,LifeOsUi.dp(this,3),0,0);c.addView(l);c.setOnClickListener(v->click.run());c.setClickable(true);c.setFocusable(true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,56),1);p.setMargins(0,0,LifeOsUi.dp(this,6),0);row.addView(c,p);}
    private void sectionRow(String title,String action,Runnable click){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(LifeOsUi.dp(this,1),LifeOsUi.dp(this,15),0,LifeOsUi.dp(this,7));TextView t=LifeOsUi.text(this,title,15.5f,LifeOsUi.TEXT);LifeOsUi.weight(t,700);r.addView(t,new LinearLayout.LayoutParams(0,-2,1));if(action!=null&&!action.isEmpty()){TextView a=LifeOsUi.text(this,action,10.5f,LifeOsUi.BLUE);LifeOsUi.weight(a,600);r.addView(a);r.setOnClickListener(v->click.run());}content.addView(r);}
    private void obligationCard(ObligationRepository.ObligationObject x){LinearLayout c=LifeOsUi.card(this);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(LifeOsUi.iconTile(this,LifeOsIconView.COMMITMENT,LifeOsUi.RED,38),new LinearLayout.LayoutParams(LifeOsUi.dp(this,38),LifeOsUi.dp(this,38)));LinearLayout txt=new LinearLayout(this);txt.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);tp.setMargins(LifeOsUi.dp(this,10),0,LifeOsUi.dp(this,5),0);row.addView(txt,tp);TextView t=LifeOsUi.text(this,x.title,12.8f,LifeOsUi.TEXT);LifeOsUi.weight(t,700);t.setMaxLines(1);txt.addView(t);TextView st=LifeOsUi.text(this,humanAction(x.action),10.3f,LifeOsUi.BLUE);LifeOsUi.weight(st,600);st.setPadding(0,LifeOsUi.dp(this,2),0,0);txt.addView(st);TextView s=LifeOsUi.text(this,x.summary,10.5f,LifeOsUi.MUTED);LifeOsUi.weight(s,500);s.setPadding(0,LifeOsUi.dp(this,3),0,0);s.setMaxLines(2);txt.addView(s);row.addView(LifeOsUi.icon(this,LifeOsIconView.CHEVRON,LifeOsUi.TERTIARY,12),new LinearLayout.LayoutParams(LifeOsUi.dp(this,12),LifeOsUi.dp(this,18)));c.addView(row);c.setOnClickListener(v->startActivity(new Intent(this,FunctionalObjectDetailActivity.class).putExtra("capability_id","commitments").putExtra("object_id",x.id)));content.addView(c);}
    private void eventCard(CalendarEventRepository.CalendarEventObject e){LinearLayout c=LifeOsUi.card(this);LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.addView(LifeOsUi.iconTile(this,LifeOsIconView.EVENT,LifeOsUi.PURPLE,38),new LinearLayout.LayoutParams(LifeOsUi.dp(this,38),LifeOsUi.dp(this,38)));LinearLayout copy=new LinearLayout(this);copy.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(LifeOsUi.dp(this,10),0,LifeOsUi.dp(this,5),0);r.addView(copy,p);TextView t=LifeOsUi.text(this,e.title.isEmpty()?"Calendar event":e.title,12.8f,LifeOsUi.TEXT);LifeOsUi.weight(t,700);copy.addView(t);TextView when=LifeOsUi.text(this,new SimpleDateFormat("EEE, d MMM · HH:mm",Locale.getDefault()).format(new Date(e.begin)),10.3f,LifeOsUi.PURPLE);LifeOsUi.weight(when,600);copy.addView(when);if(!e.location.isEmpty()){TextView loc=LifeOsUi.text(this,e.location,10.5f,LifeOsUi.MUTED);LifeOsUi.weight(loc,500);loc.setMaxLines(1);copy.addView(loc);}r.addView(LifeOsUi.icon(this,LifeOsIconView.CHEVRON,LifeOsUi.TERTIARY,12),new LinearLayout.LayoutParams(LifeOsUi.dp(this,12),LifeOsUi.dp(this,18)));c.addView(r);c.setOnClickListener(v->startActivity(new Intent(this,FunctionalObjectDetailActivity.class).putExtra("capability_id","events").putExtra("object_id",e.id)));content.addView(c);}
    private void approvalCard(PersistentActionQueue queue,PersistentActionQueue.Item x){LinearLayout c=LifeOsUi.card(this);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.addView(LifeOsUi.iconTile(this,LifeOsIconView.ACTION,LifeOsUi.GREEN,38),new LinearLayout.LayoutParams(LifeOsUi.dp(this,38),LifeOsUi.dp(this,38)));LinearLayout txt=new LinearLayout(this);txt.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);tp.setMargins(LifeOsUi.dp(this,10),0,0,0);head.addView(txt,tp);String label=UserFacingText.humanize(x.proposal.payloadSummary.isEmpty()?x.proposal.actionType:x.proposal.payloadSummary);TextView t=LifeOsUi.text(this,label,12.7f,LifeOsUi.TEXT);LifeOsUi.weight(t,700);txt.addView(t);TextView meta=LifeOsUi.text(this,"Ready for your approval",10f,LifeOsUi.GREEN);LifeOsUi.weight(meta,600);meta.setPadding(0,LifeOsUi.dp(this,2),0,0);txt.addView(meta);if(!x.proposal.target.isEmpty()){TextView target=LifeOsUi.text(this,UserFacingText.humanize(x.proposal.target),10.5f,LifeOsUi.MUTED);LifeOsUi.weight(target,500);target.setPadding(0,LifeOsUi.dp(this,3),0,0);txt.addView(target);}c.addView(head);LinearLayout a=new LinearLayout(this);a.setPadding(0,LifeOsUi.dp(this,8),0,0);Button details=LifeOsUi.button(this,"Review");details.setOnClickListener(v->startActivity(new Intent(this,SuggestedActionDetailActivity.class).putExtra("proposal_id",x.proposal.proposalId)));Button approve=LifeOsUi.primary(this,"Approve");approve.setOnClickListener(v->{queue.decide(x.proposal.proposalId,true);TeyaApprovalReceiver.executeApproved(this,x);refresh();});a.addView(details,new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,40),1));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,40),1);p.setMargins(LifeOsUi.dp(this,7),0,0,0);a.addView(approve,p);c.addView(a);content.addView(c);}
    private void quiet(String text){TextView t=LifeOsUi.text(this,text,10.7f,LifeOsUi.MUTED);LifeOsUi.weight(t,500);t.setPadding(LifeOsUi.dp(this,2),LifeOsUi.dp(this,3),0,LifeOsUi.dp(this,5));content.addView(t);}
    private static String humanAction(String a){String x=a==null?"":a.replace('_',' ').trim().toLowerCase(Locale.ROOT);if(x.isEmpty()||"none".equals(x))return "Needs attention";return Character.toUpperCase(x.charAt(0))+x.substring(1);}
    private static String greeting(){int h=Integer.parseInt(new SimpleDateFormat("H",Locale.US).format(new Date()));return h<12?"Good morning":h<18?"Good afternoon":"Good evening";}
}
